package lm

import (
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"sort"
	"testing"
	"time"
)

// tfRef is reference/dump_ace_lm_tf.py's output: fp32 logits at every
// teacher-forced step, and what bf16 (upstream's CUDA dtype) drifts from them.
const tfRef = "../../reference/out/acelmtf"

type tfCase struct {
	Rows, Lo, Hi, Steps int
	BF16KL              [][]float64 `json:"bf16_kl"`
	BF16Argmax          [][]bool    `json:"bf16_argmax"`
	BF16CFGKL           []float64   `json:"bf16_cfg_kl"`
	BF16CFGArgmax       []bool      `json:"bf16_cfg_argmax"`
}

type tfManifest struct {
	Cases   map[string]tfCase
	Tensors map[string]struct{ Shape []int }
}

// TestBankAgainstBF16 is A10's price: every teacher-forced step of every
// sampled phase (101 each), the bank's KL from fp32 at temperature 0.85
// beside upstream bf16's on the same steps. Phase 1 is over the text tokens,
// phase 2 over the codes, per CFG row and after CFG. The gate is that the
// bank's worst step is under bf16's mean step: a quantisation that stays
// inside what upstream itself serves.
func TestBankAgainstBF16(t *testing.T) {
	buf, err := os.ReadFile(filepath.Join(tfRef, "manifest.json"))
	if err != nil {
		t.Skipf("no teacher-forced reference (%v); run reference/dump_ace_lm_tf.py", err)
	}
	var tf tfManifest
	if err := json.Unmarshal(buf, &tf); err != nil {
		t.Fatal(err)
	}
	m := loadLMManifest(t)
	g := loadGPU(t)
	names := make([]string, 0, len(tf.Cases))
	for k := range tf.Cases {
		names = append(names, k)
	}
	sort.Strings(names)
	for _, name := range names {
		c := tf.Cases[name]
		var label string
		var ph int
		if _, err := fmt.Sscanf(name[len(name)-3:], "_p%d", &ph); err != nil {
			t.Fatal(name, err)
		}
		label = name[:len(name)-3]
		rows := promptRows(t, m, label, ph)
		_, toks := refInt32(t, m, fmt.Sprintf("%s_p%d_tokens", label, ph))
		want, err := os.ReadFile(filepath.Join(tfRef, name+"_logits.bin"))
		if err != nil {
			t.Fatal(err)
		}
		w := c.Hi - c.Lo
		wantAt := func(step, row int) []float32 {
			off := (step*c.Rows + row) * w * 4
			out := make([]float32, w)
			for i := range out {
				out[i] = math.Float32frombits(uint32(want[off+4*i]) | uint32(want[off+4*i+1])<<8 |
					uint32(want[off+4*i+2])<<16 | uint32(want[off+4*i+3])<<24)
			}
			return out
		}

		var pre []Tok
		for s, r := range rows {
			for i, id := range r[:len(r)-1] {
				pre = append(pre, Tok{ID: id, Slot: s, Pos: i})
			}
		}
		if _, _, err := g.Pass(pre, Range{}); err != nil {
			t.Fatal(err)
		}
		step := make([]Tok, len(rows))
		for s, r := range rows {
			step[s] = Tok{ID: r[len(r)-1], Slot: s, Pos: len(r) - 1}
		}
		var ours, theirs []float64
		agree, bfAgree := 0, 0
		var tDec time.Duration
		for i := 0; i < c.Steps; i++ {
			t0 := time.Now()
			out, _, err := g.Pass(step, Range{Lo: c.Lo, Hi: c.Hi})
			if err != nil {
				t.Fatal(err)
			}
			tDec += time.Since(t0)
			if c.Rows == 2 {
				gc := cfg(out[0], out[1], 2)
				wc := cfg(wantAt(i, 0), wantAt(i, 1), 2)
				st := compareLogits(gc, wc, 0, w)
				ours = append(ours, st.kl)
				theirs = append(theirs, c.BF16CFGKL[i])
				if st.argmax {
					agree++
				}
				if c.BF16CFGArgmax[i] {
					bfAgree++
				}
			}
			for r := range rows {
				st := compareLogits(out[r], wantAt(i, r), 0, w)
				ours = append(ours, st.kl)
				theirs = append(theirs, c.BF16KL[i][r])
				if c.Rows == 1 {
					if st.argmax {
						agree++
					}
					if c.BF16Argmax[i][r] {
						bfAgree++
					}
				}
			}
			if i+1 < c.Steps {
				for s := range step {
					step[s].ID = toks[i]
					step[s].Pos++
				}
			}
		}
		om, ox := meanMax(ours)
		bm, bx := meanMax(theirs)
		what := "argmax"
		if c.Rows == 2 {
			what = "cfg argmax"
		}
		t.Logf("%-18s %s bank: KL mean %.2e max %.2e, %s %d/%d | bf16: KL mean %.2e max %.2e, %s %d/%d | %.1f ms a step",
			name, g.o.Bank, om, ox, what, agree, c.Steps, bm, bx, what, bfAgree, c.Steps,
			float64(tDec.Microseconds())/1e3/float64(c.Steps))
		if !(ox < bm) { // NaN fails too
			t.Errorf("%s: the bank's worst KL %.2e is not under bf16's mean %.2e", name, ox, bm)
		}
	}
}

func meanMax(x []float64) (mean, mx float64) {
	for _, v := range x {
		mean += v
		mx = nanMax(mx, v)
	}
	return mean / float64(len(x)), mx
}

