p='ace/lm/gpu.go'
s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1,a
    s=s.replace(a,b)
rep('''type layerWeights struct {
	bank int
''','''type layerWeights struct {
	bank int
	kind Bank // the layer's width: Options.Bank, or fp16 for an FP16Layers one
''')
rep('''	// Bank is the layers' weight width: int8 (the zero value) or fp16.
	Bank Bank
''','''	// Bank is the layers' weight width: int8 (the zero value) or fp16.
	Bank Bank
	// FP16Layers stay fp16 on an int8 bank.
	FP16Layers []int
''')
rep('''	// Weight banks: the layers in order, a new bank when one is full, and
	// the head (fp16) in a bank of its own.
	bk := g.o.Bank
	perLayer := 0
	for _, s := range projShape {
		perLayer += bk.projBytes(s[0], s[1])
	}
	unit := 2 // what an offset counts: halves on fp16, bytes on int8
	if bk == BankQ8 {
