			if kept > 0 && cum > p {
				break walk
			}
			keep[i] = true
			kept++
			before = cum
			cum += math.Exp(float64(scores[i])-m) / z
		}
	}
	for i := range scores {
		if !keep[i] {
			scores[i] = negInf
		}
	}
	return before
