var (
	gpuOnce sync.Once
	gpuLM   *GPU
	gpuErr  error
)

// testBank is the bank the tests stage: int8 (served), or ACE_LM_BANK=fp16
// for the control.
func testBank() Bank {
	if os.Getenv("ACE_LM_BANK") == "fp16" {
		return BankFP16
	}
	return BankQ8
}

// loadGPU stages the LM once for the package's tests (4-8 GB).
func loadGPU(t testing.TB) *GPU {
	t.Helper()
	gpuOnce.Do(func() {
		dev, err := openDevice()
		if err != nil {
			gpuErr = err
			return
		}
		t0 := time.Now()
		gpuLM, gpuErr = Load(dev, lmDir, Options{MaxLen: 4096, Slots: 2, Rows: 256, Bank: testBank(),
			allSlabs: os.Getenv("ACE_LM_LADDER") != ""})
		t.Logf("staged the LM (%s bank) in %v", testBank(), time.Since(t0))
	})
	if gpuErr != nil {
		t.Skipf("no device or checkpoint: %v", gpuErr)
	}
	return gpuLM
}

